pub const fn akali_p(ctx: &Ctx) -> f32 {
    (match ctx.level as u8 {
        ..=1 => 35f32,
        2 => 38f32,
        3 => 41f32,
        4 => 44f32,
        5 => 47f32,
        6 => 50f32,
        7 => 53f32,
        8 => 62f32,
        9 => 71f32,
        10 => 80f32,
        11 => 89f32,
        12 => 98f32,
        13 => 107f32,
        14 => 122f32,
        15 => 137f32,
        16 => 152f32,
        17 => 167f32,
        18 => 182f32,
        19 => 197f32,
        20.. => 212f32,
    }) + 0.55 * ctx.ability_power
        + 0.6 * ctx.bonus_ad
}

pub const fn akali_q(ctx: &Ctx) -> f32 {
    5f32 * (9f32
        + 0.12 * ctx.ability_power
        + 0.13 * ctx.attack_damage
        + 5f32 * (-1f32 + ctx.q_level))
}

