pub const fn akshan_p(ctx: &Ctx) -> f32 {
    15f32
        + 0.6 * ctx.ability_power
        + 25f32 * (-1f32 + ctx.level)
        + 15f32
            * (-3f32 + ctx.level)
            * (-2f32 + ctx.level)
            * (-1f32 + ctx.level)
            / 6f32
        + 7.5 * (-2f32 + ctx.level) * (-1f32 + ctx.level)
}

pub const fn akshan_qmin(ctx: &Ctx) -> f32 {
    15f32
        * (3f32 + 0.046666666667 * ctx.bonus_ad + 2f32 * (-1f32 + ctx.q_level))
}

pub const fn akshan_qmax(ctx: &Ctx) -> f32 {
    90f32 + 1.4 * ctx.bonus_ad + 60f32 * (-1f32 + ctx.q_level)
}

pub const fn akshan_e(ctx: &Ctx) -> f32 {
    8f32 * (1f32 + 0.003 * ctx.attack_speed)
        * (0.03125 * ctx.attack_damage + ctx.e_level)
}

pub const fn akshan_rmin(ctx: &Ctx) -> f32 {
    5f32 * (5f32 + 0.03 * ctx.attack_damage + 2f32 * (-1f32 + ctx.r_level))
}

pub const fn akshan_r1min(ctx: &Ctx) -> f32 {
    125f32
        + 85f32 * (-1f32 + ctx.r_level)
        + ctx.attack_damage * (0.75 + 0.075 * (-1f32 + ctx.r_level))
        + 10f32 * (-2f32 + ctx.r_level) * (-1f32 + ctx.r_level)
}

pub const fn akshan_rmax(ctx: &Ctx) -> f32 {
    15f32 * (5f32 + 0.03 * ctx.attack_damage + 2f32 * (-1f32 + ctx.r_level))
}

pub const fn akshan_r1max(ctx: &Ctx) -> f32 {
    375f32
        + 255f32 * (-1f32 + ctx.r_level)
        + ctx.attack_damage * (2.25 + 0.225 * (-1f32 + ctx.r_level))
        + 30f32 * (-2f32 + ctx.r_level) * (-1f32 + ctx.r_level)
}

