pub const fn illaoi_p1(ctx: &Ctx) -> f32 {
    9f32 + 1.1 * ctx.attack_damage + 171f32 * (-1f32 + ctx.level) / 17f32
}

pub const fn illaoi_p2(ctx: &Ctx) -> f32 {
    0.4 * ctx.ability_power
}

pub const fn illaoi_p3(ctx: &Ctx) -> f32 {
    0.3 * ctx.steelcaps_effect
}

pub const fn illaoi_q(ctx: &Ctx) -> f32 {
    5f32 * (1f32 + ctx.q_level)
}

pub const fn illaoi_wmin(ctx: &Ctx) -> f32 {
    10f32 * (1f32 + ctx.w_level)
}

pub const fn illaoi_wmax(ctx: &Ctx) -> f32 {
    0.00035 * ctx.attack_damage
        + ctx.enemy_max_health * (0.03 + 0.005 * (-1f32 + ctx.w_level))
}

pub const fn illaoi_e(ctx: &Ctx) -> f32 {
    5f32 * (4f32 + 0.00016 * ctx.attack_damage + ctx.e_level)
}

pub const fn illaoi_r(ctx: &Ctx) -> f32 {
    150f32 + 100f32 * (-1f32 + ctx.r_level) + ctx.bonus_ad / 2f32
}

